from __future__ import annotations

import datetime as dt
import sys
from pathlib import Path

import polars as pl
import pytest
from ds.data.raw.gateway import Limits, SpendingLimits

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui import spend  # noqa: E402

UTC = pl.Datetime("us", "UTC")
NOW = dt.datetime(2026, 11, 17, 15, 0, tzinfo=dt.UTC)  # a Tuesday


def _hourly(costs: dict[dt.datetime, float]) -> pl.DataFrame:
    rows = [(hour, "agent", "m", 1, 1, 10, 5, cost) for hour, cost in costs.items()]
    schema = ["hour", "agent", "model", "requests", "priced", "input_tokens", "output_tokens", "cost"]
    return pl.DataFrame(rows, schema=schema, orient="row").with_columns(pl.col("hour").cast(UTC))


def _top() -> pl.DataFrame:
    schema = {"start_at": UTC, "trace_id": pl.String, "agent": pl.String, "model": pl.String}
    return pl.DataFrame(schema={**schema, "input_tokens": pl.Int64, "output_tokens": pl.Int64, "cost": pl.Float64})


def _limits(project: Limits, org: Limits | None = None) -> SpendingLimits:
    return SpendingLimits(organization=org or Limits(), project=project, project_name="delulu-smash")


def test_the_month_starts_on_the_utc_first():
    assert spend.month_start(dt.date(2026, 11, 17)) == dt.date(2026, 11, 1)


@pytest.mark.parametrize(
    ("peak", "top"), [(0, 1.0), (0.04, 0.05), (0.3, 0.5), (1.3, 2.0), (2.0, 2.0), (7, 10.0), (12, 20.0)]
)
def test_nice_top_rounds_up_to_1_2_5(peak: float, top: float):
    assert spend.nice_top(peak) == pytest.approx(top)


def test_tightest_picks_the_lower_monthly_cap_and_names_it():
    assert _limits(Limits(monthly=5), Limits(monthly=100)).tightest() == (5, "project")
    assert _limits(Limits(), Limits(monthly=15)).tightest() == (15, "organization")
    assert _limits(Limits()).tightest() == (None, "")


def test_the_one_tile_is_the_month_against_its_cap():
    hourly = _hourly(
        {
            NOW: 0.5,
            NOW - dt.timedelta(days=1): 1.0,
            dt.datetime(2026, 11, 3, tzinfo=dt.UTC): 2.5,
            dt.datetime(2026, 10, 30, tzinfo=dt.UTC): 9.0,  # last month: not counted
        }
    )
    view = spend.build(hourly, _top(), "UTC", NOW, limits=_limits(Limits(monthly=5)))
    [month] = view.tiles
    assert (month["label"], month["value"]) == ("This month", "$4.00")
    assert (month["limit"], month["share"], month["meter"], month["level"]) == (
        "of $5.00",
        "$1.00 remaining · 80% used",
        "80.0%",
        "warn",
    )
    assert view.limits == "Limits: project delulu-smash $5/month · organization none"


def test_meter_is_full_and_danger_past_the_cap():
    tile = spend.tile("This month", _hourly({NOW: 6.0}), 5, limits_known=True)
    assert (tile["share"], tile["meter"], tile["level"]) == ("$1.00 over · 120% used", "100.0%", "danger")


def test_without_limits_tiles_show_spend_and_the_reason():
    view = spend.build(_hourly({NOW: 0.5}), _top(), "UTC", NOW, limits=None, limits_problem="needs a scope")
    assert all(tile["limit"] == "· limit unknown" and tile["meter"] == "" for tile in view.tiles)
    assert view.limits == "needs a scope"


def test_axis_is_a_readable_scale_and_bars_use_it():
    view = spend.build(_hourly({NOW: 1.3}), _top(), "UTC", NOW)
    assert [tick["label"] for tick in view.axis] == ["$2", "$1", "$0"]
    assert view.bars[-1]["height"] == "65.0%"  # $1.30 of a $2 scale, not 100% of the peak


def test_the_gateway_spending_page_is_the_organizations() -> None:
    url = spend.gateway_url("https://logfire-us.pydantic.dev/delulu-smash/delulu-smash")
    assert url == "https://logfire-us.pydantic.dev/delulu-smash/-/gateway/spending/organization"
    settings = spend.gateway_url("https://logfire-us.pydantic.dev/delulu-smash/delulu-smash", "settings")
    assert settings == "https://logfire-us.pydantic.dev/delulu-smash/-/gateway/settings"
    assert spend.gateway_url("") == ""


def test_title_bar_meter_is_the_month_only():
    hourly = _hourly({NOW: 0.5, dt.datetime(2026, 11, 3, tzinfo=dt.UTC): 1.41})
    view = spend.build(hourly, _top(), "UTC", NOW, limits=_limits(Limits(), org=Limits(monthly=15)))
    assert view.as_of == "11/17 15:00"  # NOW, in the chart's zone
    assert view.meters == [
        {
            "text": "month $1.91 / $15 (13%)",
            "meter": "12.7%",
            "level": "ok",
            "title": "$13.09 remaining · organization limit, this month (UTC). Click for the Spend tab.",
        }
    ]
    no_cap = spend.build(hourly, _top(), "UTC", NOW, limits=_limits(Limits())).meters
    assert [m["text"] for m in no_cap] == ["month $1.91 · no limit"]
    assert [m["text"] for m in spend.placeholder_meters()] == ["month $-- / $-- (--%)"]


def test_costs_are_never_in_scientific_notation():
    from ui.session import cost_text  # beside the spend tests, where its text shows

    assert [cost_text(c) for c in (None, 0, 0.0001, 0.000025, 0.0011, 0.072, 1.91)] == [
        "$?",
        "$0",
        "$0.0001",
        "$0.000025",
        "$0.0011",
        "$0.072",
        "$1.91",
    ]
